'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',tasks:'M9 5h11v15H4V5h2 M9 3h6v4H9Z M8 13l2 2 5-5',calendar:'M4 5h16v16H4Z M7 3v4 M17 3v4 M4 10h16 M8 14h2 M14 14h2',users:'M16 21v-3a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v3 M9.5 10a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7 M16 4a3 3 0 0 1 0 6 M21 21v-3a4 4 0 0 0-3-4',check:'M5 12l4 4L20 5 M20 12v8H4V4h10',note:'M5 3h14v18H5Z M9 8h6 M9 12h6 M9 16h4',phone:'M8 3H4v5c0 7 5 12 12 12h5v-4l-5-2-2 2-6-6 2-2Z',wallet:'M3 6h17v15H3Z M3 6V3h14v3 M15 11h6v5h-6Z',link:'M10 14l4-4 M8 16l-1 1a3 3 0 0 1-4-4l5-5a3 3 0 0 1 4 0 M12 16a3 3 0 0 0 4 0l5-5a3 3 0 0 0-4-4l-1 1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3Z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',edit:'M14 4l6 6 M4 20l5-1L21 7l-5-5L4 14Z',trash:'M3 6h18 M9 3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',close:'M5 5l14 14 M19 5 5 19',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',menu:'M4 6h16 M4 12h16 M4 18h16',leaf:'M20 3C5 2 2 9 7 15s14 1 13-12Z M4 21 16 9',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.note}"/></svg>`;
const uid=()=>crypto.randomUUID();
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateText=d=>new Date(d+'T00:00:00').toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'});
const money=n=>Number(n||0).toLocaleString('ko-KR')+'원';
const blank=()=>({version:1,demo:false,schoolName:'',schoolYear:new Date().getFullYear(),grade:'',room:'',className:'우리 반',teacher:'선생님',budget:500000,students:[],tasks:[],events:[],notes:[],contacts:[],checks:[],expenses:[],items:[],links:[],attendance:{},daily:{}});
function sample(){const d=blank();d.demo=true;d.className='함께 자라는 우리 반';d.students=['가람','다온','서우','이든','하람','지안'].map((name,i)=>({id:uid(),name,number:i+1,support:['활동 전에 순서를 짧게 안내해요.','선택할 시간을 충분히 기다려요.','말과 그림을 함께 제시해요.','','',''][i]}));d.tasks=[['체험학습 동의서 확인','학급 운영',false],['다음 주 수업자료 준비','수업 준비',false],['학부모 상담 일정 정리','보호자 연락',false],['학급 물품 정리','학급 운영',true]].map(([title,category,done])=>({id:uid(),title,category,done,date:today()}));d.events=[['09:00','아침 맞이 · 하루 열기','교실'],['10:40','생활 속 수학','교실'],['14:30','개별 상담','상담실']].map(([time,title,place])=>({id:uid(),time,title,place,date:today()}));d.checks=[{id:uid(),title:'체험학습 동의서',date:today(),checked:d.students.slice(0,4).map(x=>x.id)},{id:uid(),title:'개인 준비물',date:today(),checked:d.students.slice(0,2).map(x=>x.id)}];d.notes=[{id:uid(),student:d.students[0].id,date:today(),category:'관찰 기록',content:'활동 순서를 확인한 뒤 준비물을 스스로 챙겼어요.'}];d.items=[{id:uid(),title:'화이트보드 마커',quantity:4,memo:'다음 달 추가 구매 확인'}];d.expenses=[{id:uid(),title:'수업 활동 재료',amount:18000,date:today(),category:'수업 재료'}];return d;}
let archive, state, activeYear, savedYear, storageUnreadable = false;
try {
  archive = SchoolYears.open(localStorage, sample);
  activeYear = archive.activeYear;
  state = structuredClone(archive.years[activeYear]);
  savedYear = JSON.stringify(state);
} catch {
  storageUnreadable = true;
  state = blank();
  activeYear = state.schoolYear;
}
let page='home',filter='',selectedDate=today(),studentFilter='',selectedCheck='';
let modalSave=null;

function persist() {
  if (storageUnreadable) {
    toast('기존 기록을 읽지 못했습니다. 저장된 자료를 확인해 주세요.');
    return false;
  }
  try {
    const latest = SchoolYears.read(localStorage);
    const next = JSON.stringify(state);
    if (latest && next === savedYear) return true;
    if (latest && JSON.stringify(latest.years[activeYear]) !== savedYear) {
      toast('다른 탭에서 이 학년도를 수정했어요. 새로고침해 주세요.');
      return false;
    }
    archive = SchoolYears.write(localStorage, {
      ...(latest || archive),
      years: { ...(latest || archive).years, [activeYear]: state }
    });
    savedYear = next;
    return true;
  } catch {
    toast('저장하지 못했어요. 저장 공간과 브라우저 설정을 확인해 주세요.');
    return false;
  }
}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
const menus=[['home','오늘의 학급','home'],['tasks','할 일','tasks'],['events','학급 일정','calendar'],['attendance','출결 관리','check'],['students','학생 정보 · 기록','users'],['checks','제출 · 준비물','note'],['contacts','보호자 연락','phone'],['finance','예산 · 물품','wallet'],['links','자료 바로가기','link'],['settings','설정 · 백업','settings']];
const match=(...s)=>s.join(' ').toLowerCase().includes(filter.toLowerCase());
const empty=(s,action='')=>`<div class="empty">${icon('leaf')}<p>${s}</p>${action}</div>`;
const addBtn=(label,type)=>`<button class="btn primary" data-add="${type}">${icon('plus')}${label}</button>`;
const actions=(type,id)=>`<div class="actions"><button data-edit="${type}" data-id="${esc(id)}" aria-label="수정">${icon('edit')}</button><button data-delete="${type}" data-id="${esc(id)}" aria-label="삭제">${icon('trash')}</button></div>`;
function shell(){const n=menus.find(x=>x[0]===page);$('#app').innerHTML=`<aside><button type="button" class="brand" data-page="home" aria-label="하루반 홈으로 이동" title="오늘의 학급으로 이동"><span class="brandmark">${icon('leaf')}</span>하루반<span style="color:#c4cfb9;font-size:24px">.</span></button><div class="brand-sub">TEACHER’S DAILY NOTE</div><div class="classbox"><div class="classbox-heading"><small>${esc(state.schoolYear||new Date().getFullYear())}학년도 · 나의 학급</small><button type="button" class="class-edit" data-action="edit-class" aria-label="학급 정보 수정" title="학급 정보 수정">${icon('edit')}</button></div><strong>${esc(state.className)}</strong>${state.schoolName?`<span class="classbox-school">${esc(state.schoolName)}${state.grade?' · '+esc(state.grade):''}</span>`:''}<button type="button" class="class-edit-link" data-action="edit-class">학급 정보 수정</button></div><div class="nav-label">MY CLASSROOM</div><nav>${menus.map(([id,label,ic])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(ic)}${label}</button>`).join('')}</nav><div class="sidefoot">작은 기록이 모여<br>우리 반의 하루가 됩니다.<button class="btn" data-action="export">${icon('download')}기록 백업하기</button></div></aside><div class="layout"><header><button class="menu-toggle" data-action="menu" aria-label="메뉴 열기">${icon('menu')}</button><div class="breadcrumb">나의 교실 <span style="margin:0 12px;color:#c7cdc1">/</span> <b>${n[1]}</b></div><div class="header-right"><label class="search">${icon('search')}<input id="search" aria-label="현재 화면에서 검색" placeholder="이 화면에서 검색" value="${esc(filter)}"></label><span class="header-date">${dateText(today())}</span><span class="avatar" title="${esc(state.teacher)}">${esc(state.teacher.slice(0,1))}</span></div></header><main><div id="content"></div><div class="footer"><span>하루반 · 선생님의 하루에 작은 여유를</span><span>이 브라우저에 자동 저장 · 설정에서 백업할 수 있어요</span></div></main></div>`;renderContent();}
function heading(title,sub,button=''){return `<div class="title-row"><div><p class="eyebrow">${page==='home'?'A LITTLE MORE ROOM IN YOUR DAY':'MY CLASSROOM NOTE'}</p><h1>${title}</h1><p class="sub">${sub}</p></div>${button}</div>`}
function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><input type="checkbox" aria-label="${esc(t.title)} 완료" data-task="${t.id}" ${t.done?'checked':''}><span class="task-title">${esc(t.title)}</span><span class="badge ${t.category==='보호자 연락'?'orange':''}">${esc(t.category)}</span></div>`}
function attendanceSummary(){const a=state.attendance[today()]||{};return {present:state.students.filter(s=>a[s.id]?.status==='출석').length,total:state.students.length,unmarked:state.students.filter(s=>!a[s.id]?.status||a[s.id].status==='미확인').length};}
function dashboard(){const a=attendanceSummary(),tasks=state.tasks.filter(t=>!t.done),events=state.events.filter(e=>e.date===today()&&match(e.title,e.place)).sort((a,b)=>a.time.localeCompare(b.time));const missing=state.checks.reduce((n,c)=>n+state.students.filter(s=>!c.checked.includes(s.id)).length,0);const spent=state.expenses.reduce((n,e)=>n+Number(e.amount),0);return heading(`반가워요, ${esc(state.teacher)}.`,`오늘도 우리 반의 하루를 차근차근 시작해요.`,addBtn('할 일 추가','tasks'))+`<section class="hero"><div><span class="pill">${dateText(today())}</span><h2>오늘의 작은 기록, 더 여유로운 내일.</h2><p>챙길 일은 이곳에 두고, 학생들과의 시간에 집중하세요.</p></div><div class="hero-art" aria-hidden="true"><div class="art-circle"></div><div class="art-book"><i></i><i></i><i style="width:65%"></i></div><div class="art-pencil"></div><div class="art-star">✦</div></div></section><div class="stats">${[['오늘 출결',`${a.present}<small>/ ${a.total}명 출석</small>`,a.unmarked?`${a.unmarked}명 아직 확인 전`:'모두 확인했어요','users','attendance'],['남은 할 일',`${tasks.length}<small>건</small>`,'하나씩 마무리해 보세요','tasks','tasks'],['미제출 확인',`${missing}<small>건</small>`,'학생별 제출 현황 확인','note','checks'],['남은 학급 예산',`${((Number(state.budget)-spent)/10000).toLocaleString('ko-KR',{maximumFractionDigits:1})}<small>만원</small>`,`사용 ${money(spent)}`,'wallet','finance']].map(([label,val,note,ic,pg])=>`<button class="stat" data-page="${pg}" style="text-align:left;color:inherit;font:inherit;cursor:pointer"><div class="stat-label">${label}</div><div class="stat-value">${val}</div><div class="stat-note">${note} ${icon('arrow').replace('<svg','<svg style="width:12px;height:12px"')}</div><span class="stat-icon">${icon(ic)}</span></button>`).join('')}</div><div class="grid-main"><section class="card"><div class="card-head"><h2>${icon('tasks')}놓치지 않을 할 일 <span class="badge">${tasks.length}</span></h2><button class="text-btn" data-page="tasks">전체 보기 ${icon('arrow')}</button></div>${state.tasks.filter(t=>match(t.title,t.category)).sort((a,b)=>Number(a.done)-Number(b.done)).slice(0,4).map(taskRow).join('')||empty('아직 할 일이 없어요.',addBtn('할 일 추가','tasks'))}</section><section class="card"><div class="card-head"><h2>${icon('calendar')}오늘의 일정</h2><button class="text-btn" data-page="events">일정 보기 ${icon('arrow')}</button></div>${events.map(e=>`<div class="timeline-row"><span class="timeline-time">${esc(e.time)}</span><span class="timeline-line"></span><div class="timeline-copy">${esc(e.title)}<small>${esc(e.place||'장소 미지정')}</small></div></div>`).join('')||empty('오늘은 등록된 일정이 없어요.',addBtn('일정 추가','events'))}</section></div><div class="bottom-grid"><section class="card"><div class="card-head"><h2>빠르게 기록해요</h2><span class="small muted">QUICK NOTE</span></div><div class="quick-grid">${[['notes','note','학생 관찰'],['contacts','phone','보호자 연락'],['expenses','wallet','지출 기록'],['events','calendar','일정 추가']].map(([type,ic,label])=>`<button class="quick" data-add="${type}">${icon(ic)}${label}</button>`).join('')}</div></section><section class="card"><div class="card-head"><h2>한 번 더 챙겨요</h2><button class="text-btn" data-page="checks" aria-label="제출·준비물 전체 보기">${icon('arrow')}</button></div>${state.checks.slice(0,3).map(c=>{const count=state.students.filter(s=>c.checked.includes(s.id)).length;return `<div class="notice"><div style="flex:1">${esc(c.title)}<div class="progress"><span style="width:${state.students.length?count/state.students.length*100:0}%"></span></div></div><span class="small muted">${count}/${state.students.length}명</span></div>`}).join('')||'<p class="sub">제출·준비물 항목을 추가해 보세요.</p>'}</section><section class="card"><div class="card-head"><h2>오늘의 메모</h2><span class="small muted" id="memo-status">자동 저장</span></div><textarea class="daily-note" id="daily-note" aria-label="오늘의 메모" placeholder="오늘 기억할 일이나 내일 챙길 일을 적어 두세요.">${esc(state.daily[today()]||'')}</textarea><p class="small muted" style="margin-bottom:0">가볍게 적어 두면 마음이 조금 편해져요.</p></section></div>${state.demo?'<div class="demo-banner">현재 예시 자료를 보고 있어요. 학생 이름과 기록은 모두 가상입니다.<button class="text-btn" data-action="fresh">내 학급으로 시작하기 →</button></div>':''}`;}
function tasksView(){const rows=state.tasks.filter(t=>match(t.title,t.category));return heading('챙길 일을 가볍게 정리해요.','완료한 일은 체크하고, 다음 할 일을 기록하세요.',addBtn('할 일 추가','tasks'))+`<div class="card">${rows.map(t=>`<div style="display:flex;align-items:center;gap:12px"><div style="flex:1">${taskRow(t)}</div><span class="small muted">${esc(t.date)}</span>${actions('tasks',t.id)}</div>`).join('')||empty('등록된 할 일이 없어요.')}</div>`;}
function eventView(){const rows=state.events.filter(e=>e.date===selectedDate&&match(e.title,e.place)).sort((a,b)=>a.time.localeCompare(b.time));return heading('우리 반의 일정을 한곳에.','날짜를 골라 수업, 행사, 상담 일정을 확인하세요.',addBtn('일정 추가','events'))+`<div class="toolbar"><label class="sr-only" for="date-select">일정 날짜</label><input type="date" id="date-select" value="${selectedDate}"><button class="btn" data-action="today">오늘</button><span class="muted small">${rows.length}개의 일정</span></div><div class="list">${rows.map(e=>`<div class="record"><div class="record-details"><span class="badge">${esc(e.time)}</span><h3 style="margin-top:12px">${esc(e.title)}</h3><p class="muted">${esc(e.place||'장소 미지정')}</p></div>${actions('events',e.id)}</div>`).join('')||empty('이 날짜에는 일정이 없어요.',addBtn('일정 추가','events'))}</div><div class="card" style="margin-top:22px"><div class="card-head"><h2>다가오는 일정</h2></div>${state.events.filter(e=>e.date>selectedDate&&match(e.title,e.place)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,8).map(e=>`<div class="notice"><span>${esc(e.date)} · ${esc(e.time)}</span><span>${esc(e.title)}</span></div>`).join('')||'<p class="sub">다음 일정이 아직 없어요.</p>'}</div>`;}
function attendanceView(){const a=state.attendance[selectedDate]||{};return heading('하루의 시작, 출결 확인.','날짜별로 출결과 간단한 사유를 남겨요.')+`<div class="toolbar"><input type="date" id="date-select" aria-label="출결 날짜" value="${selectedDate}"><button class="btn" data-action="all-present">모두 출석으로 표시</button><button class="btn" data-action="attendance-xlsx">${icon('download')}이 날짜 엑셀</button></div>${state.students.length?`<div class="table-wrap"><table><thead><tr><th>번호</th><th>학생</th><th>출결 상태</th><th>사유 · 메모</th></tr></thead><tbody>${state.students.filter(s=>match(s.name)).map(s=>`<tr><td>${esc(s.number)}</td><td><b>${esc(s.name)}</b></td><td><select data-attendance="${s.id}" aria-label="${esc(s.name)} 출결">${['미확인','출석','결석','지각','조퇴','체험학습'].map(x=>`<option ${(a[s.id]?.status||'미확인')===x?'selected':''}>${x}</option>`).join('')}</select></td><td><input data-attendance-memo="${s.id}" aria-label="${esc(s.name)} 출결 메모" placeholder="간단한 메모" value="${esc(a[s.id]?.memo||'')}"></td></tr>`).join('')}</tbody></table></div>`:empty('학생을 먼저 등록해 주세요.',addBtn('학생 추가','students'))}`;}
function studentView(){const students=state.students.filter(s=>match(s.name,s.support,s.memo));const notes=state.notes.filter(n=>(!studentFilter||n.student===studentFilter)&&match(n.content,n.activity,n.domain,n.assistance,n.response,n.strength,n.nextSupport,n.iepGoal,state.students.find(s=>s.id===n.student)?.name,n.category)).sort((a,b)=>b.date.localeCompare(a.date));return heading('학생의 하루를 차곡차곡.','학생 정보를 수정하고, 지원 방법과 관찰 내용을 함께 관리해요.',addBtn('학생 추가','students'))+`<div class="student-grid">${students.map(s=>`<article class="student"><div class="student-top"><span class="student-avatar">${esc(s.name.slice(0,1))}</span><div><h3>${esc(s.name)}</h3><small class="muted">${esc(s.number)}번 · 기록 ${state.notes.filter(n=>n.student===s.id).length}개</small></div><div class="actions" style="margin-left:auto"><button data-delete="students" data-id="${s.id}" aria-label="${esc(s.name)} 학생 삭제">${icon('trash')}</button></div></div><span class="badge">도움이 되는 지원</span><p>${esc(s.support||'필요한 지원 방법을 적어 주세요.')}</p>${s.memo?`<p class="student-memo"><b>학생 메모</b><br>${esc(s.memo)}</p>`:''}<div class="student-card-actions"><button class="btn" data-edit="students" data-id="${s.id}" aria-label="${esc(s.name)} 정보 수정">${icon('edit')}정보 수정</button><button class="btn" data-add="notes" data-student="${s.id}">${icon('plus')}관찰 기록</button></div></article>`).join('')}</div>${!state.students.length?empty('함께할 학생을 등록해 주세요.',addBtn('학생 추가','students')):''}<div class="card-head" style="margin-top:32px"><h2>학생 기록 모아보기</h2>${addBtn('기록 추가','notes')}</div><div class="toolbar"><select id="student-filter" aria-label="학생별 기록 필터"><option value="">모든 학생</option>${state.students.map(s=>`<option value="${s.id}" ${studentFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="list">${notes.map(n=>`<div class="record"><div class="record-details"><span class="badge">${esc(state.students.find(s=>s.id===n.student)?.name||'삭제된 학생')}</span> <span class="small muted">${esc(n.date)}${n.time?' '+esc(n.time):''} · ${esc(n.category)}</span>${n.domain?` <span class="badge blue">${esc(n.domain)}</span>`:''}${n.activity?`<h3 class="observation-activity">${esc(n.activity)}</h3>`:''}<p>${esc(n.content)}</p>${observationDetails(n)}</div>${actions('notes',n.id)}</div>`).join('')||empty('아직 남긴 기록이 없어요.')}</div>`;}
function checksView(){const rows=state.checks.filter(c=>match(c.title));if(!rows.some(c=>c.id===selectedCheck))selectedCheck=rows[0]?.id||'';const c=rows.find(x=>x.id===selectedCheck);return heading('제출과 준비, 한눈에 확인.','학생별로 체크하면 미확인 항목을 바로 알 수 있어요.',addBtn('확인 항목 추가','checks'))+`<div class="toolbar">${rows.map(c=>`<button class="btn ${selectedCheck===c.id?'primary':''}" data-check-tab="${c.id}">${esc(c.title)}</button>`).join('')}</div>${c?`<div class="card"><div class="card-head"><h2>${esc(c.title)} <span class="small muted">기한 ${esc(c.date||'없음')}</span></h2>${actions('checks',c.id)}</div><div class="toolbar"><span class="sub">${state.students.filter(s=>c.checked.includes(s.id)).length} / ${state.students.length}명 확인</span><button class="btn" data-action="check-all">모두 확인</button></div><div class="table-wrap"><table><thead><tr><th>확인</th><th>번호</th><th>학생</th><th>상태</th></tr></thead><tbody>${state.students.map(s=>`<tr><td><input type="checkbox" data-check-student="${s.id}" aria-label="${esc(s.name)} ${esc(c.title)} 확인" ${c.checked.includes(s.id)?'checked':''}></td><td>${esc(s.number)}</td><td>${esc(s.name)}</td><td><span class="badge ${c.checked.includes(s.id)?'':'orange'}">${c.checked.includes(s.id)?'확인 완료':'확인 전'}</span></td></tr>`).join('')}</tbody></table></div>${!state.students.length?'<p class="sub">학생을 먼저 등록해 주세요.</p>':''}</div>`:empty('확인할 제출물이나 준비물을 추가해 주세요.',addBtn('확인 항목 추가','checks'))}`;}
function contactsView(){const rows=state.contacts.filter(c=>match(c.content,c.followup,state.students.find(s=>s.id===c.student)?.name)).sort((a,b)=>b.date.localeCompare(a.date));return heading('연락 내용도 놓치지 않도록.','보호자와 나눈 내용, 다음에 챙길 일을 함께 남겨요.',addBtn('연락 기록 추가','contacts'))+`<div class="list">${rows.map(c=>`<div class="record"><div class="record-details"><span class="badge">${esc(state.students.find(s=>s.id===c.student)?.name||'삭제된 학생')}</span> <span class="small muted">${esc(c.date)} · ${esc(c.method)}</span><p>${esc(c.content)}</p>${c.followup?`<p class="small" style="color:var(--orange)">다음 할 일 · ${esc(c.followup)}</p>`:''}</div>${actions('contacts',c.id)}</div>`).join('')||empty('연락 내용을 짧게 남겨 보세요.',addBtn('연락 기록 추가','contacts'))}</div>`;}
function financeView(){const spent=state.expenses.reduce((n,e)=>n+Number(e.amount),0);return heading('학급 살림을 간단하게.','지출 내역과 필요한 물품을 함께 관리해요.',addBtn('지출 기록','expenses'))+`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${[['전체 예산',state.budget],['사용한 금액',spent],['남은 예산',state.budget-spent]].map(([l,n])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-value" style="font-size:22px">${money(n)}</div></div>`).join('')}</div><div class="card-head"><h2>지출 내역</h2><button class="btn" data-action="expenses-csv">${icon('download')}CSV 내려받기</button></div><div class="list">${state.expenses.filter(e=>match(e.title,e.category)).sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="record"><div class="record-details"><h3>${esc(e.title)}</h3><p class="muted small">${esc(e.date)} · ${esc(e.category)}</p></div><b class="money">${money(e.amount)}</b>${actions('expenses',e.id)}</div>`).join('')||empty('아직 등록된 지출이 없어요.')}</div><div class="card-head" style="margin-top:32px"><h2>학급 물품</h2>${addBtn('물품 추가','items')}</div><div class="list">${state.items.filter(i=>match(i.title,i.memo)).map(i=>`<div class="record"><div class="record-details"><h3>${esc(i.title)} <span class="badge">${esc(i.quantity)}개</span></h3><p class="sub">${esc(i.memo)}</p></div>${actions('items',i.id)}</div>`).join('')||empty('관리할 물품을 추가해 주세요.')}</div>`;}
function linksView(){return heading('자주 쓰는 자료, 바로 열어요.','시간표, 수업자료, 학교 업무 링크를 모아 두세요.',addBtn('바로가기 추가','links'))+`<div class="list">${state.links.filter(l=>match(l.title,l.memo)).map(l=>`<div class="record"><div class="record-details"><a class="resource-link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener noreferrer">${icon('link')} ${esc(l.title)} ↗</a><p class="sub">${esc(l.memo)}</p></div>${actions('links',l.id)}</div>`).join('')||empty('자주 여는 자료의 링크를 등록해 주세요.',addBtn('바로가기 추가','links'))}</div>`;}
function classInfoFields(){return `<label class="field">학교 이름 (선택)<input name="schoolName" value="${esc(state.schoolName||'')}" maxlength="80" placeholder="예: 함께학교"></label><div class="class-form-row"><label class="field">학년도<input name="schoolYear" type="number" readonly value="${esc(state.schoolYear||new Date().getFullYear())}" required></label><label class="field">학년 (선택)<input name="grade" value="${esc(state.grade||'')}" maxlength="30" placeholder="예: 중학교 2학년"></label></div><label class="field">학급 이름<input name="className" value="${esc(state.className)}" required maxlength="40"></label><label class="field">담임 이름 또는 호칭<input name="teacher" value="${esc(state.teacher)}" required maxlength="30"></label><label class="field">교실 (선택)<input name="room" value="${esc(state.room||'')}" maxlength="60" placeholder="예: 본관 2층 201호"></label><label class="field">전체 학급 예산 (원)<input name="budget" type="number" min="0" max="10000000000" value="${Number(state.budget)}" required></label>`;}
function editClassInfo(){$('#modal').innerHTML=`<form id="settings-form"><div class="modal-head"><h2>학급 정보 수정</h2><button type="button" class="text-btn" data-action="close" aria-label="닫기">${icon('close')}</button></div>${classInfoFields()}<div class="modal-foot"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary">학급 정보 저장</button></div></form>`;$('#modal').showModal();}
function settingsView(){return heading('내 학급에 맞게 준비해요.','학급 정보와 기록 백업을 관리하세요.')+`<section class="card setting-group"><h2>학급 정보</h2><form id="settings-form">${classInfoFields()}<button class="btn primary">학급 정보 저장</button></form></section><section class="card setting-group"><h2>기록 저장과 백업</h2><p>기록은 이 기기의 현재 브라우저에 자동 저장됩니다. 다른 기기와 자동으로 동기화되지 않아요. 브라우저 데이터를 지우기 전에는 백업 파일을 내려받아 주세요.</p><div class="toolbar"><button class="btn" data-action="export">${icon('download')}현재 학년도 백업</button><button class="btn" data-action="import">백업 불러오기</button><input id="import-file" type="file" accept="application/json,.json" hidden></div><p class="small">백업 파일에는 학생 기록이 포함됩니다. 교사가 관리하는 곳에 보관해 주세요.</p></section><section class="card setting-group"><h2>새로 시작하기</h2><p>현재 기록을 비우거나, 기능을 살펴볼 예시 자료를 불러올 수 있어요.</p><div class="toolbar"><button class="btn danger" data-action="fresh">현재 학년도 기록 비우기</button><button class="btn" data-action="sample">예시 자료 불러오기</button></div></section>`;}
function renderContent(){const views={home:dashboard,tasks:tasksView,events:eventView,attendance:attendanceView,students:studentView,checks:checksView,contacts:contactsView,finance:financeView,links:linksView,settings:settingsView};$('#content').innerHTML=views[page]();}
function go(p){page=p;filter='';studentFilter='';document.body.classList.remove('nav-open');shell();window.scrollTo({top:0,behavior:'smooth'});}
const safeUrl=u=>{try{const url=new URL(u);return ['https:','http:'].includes(url.protocol)?url.href:'#';}catch{return '#'}};
const studentOptions=()=>state.students.map(s=>[s.id,s.name]);
function fields(type){const base={tasks:[['title','할 일','text'],['date','날짜','date'],['category','분류',['학급 운영','수업 준비','보호자 연락','행정 업무','기타']]],events:[['title','일정 이름','text'],['date','날짜','date'],['time','시간','time'],['place','장소','text',true]],students:[['name','학생 이름','text'],['number','번호','number'],['support','도움이 되는 지원 방법','textarea',true],['memo','학생 메모','textarea',true]],notes:[['student','학생',studentOptions()],['date','관찰 날짜','date'],['time','관찰 시간','time',true],['category','기록 종류',['관찰 기록','상담 기록','성취 기록','지원 메모']],['domain','관찰 영역',[['','미분류'],'의사소통','학습','일상생활','또래 관계','신체활동','기타'],true],['activity','활동 · 상황','text'],['content','관찰 내용','textarea'],['assistance','제공한 도움','textarea',true],['response','학생의 반응','textarea',true],['strength','강점 · 변화','textarea',true],['nextSupport','다음 지원','textarea',true],['iepGoal','연결한 개별화교육 목표','textarea',true]],contacts:[['student','학생',studentOptions()],['date','연락 날짜','date'],['method','연락 방법',['전화','문자','대면 상담','알림장','기타']],['content','전달 · 상담 내용','textarea'],['followup','다음에 챙길 일','textarea',true]],checks:[['title','제출물 · 준비물 이름','text'],['date','확인 기한','date']],expenses:[['title','사용 내역','text'],['amount','금액 (원)','number'],['date','사용 날짜','date'],['category','분류',['수업 재료','학급 물품','체험 활동','기타']]],items:[['title','물품 이름','text'],['quantity','수량','number'],['memo','메모','textarea',true]],links:[['title','자료 이름','text'],['url','주소 (https://...)','url'],['memo','메모','textarea',true]]};return base[type];}
const labels={tasks:'할 일',events:'일정',students:'학생 정보',notes:'학생 기록',contacts:'연락 기록',checks:'확인 항목',expenses:'지출',items:'물품',links:'바로가기'};
const observationExtraFields=[['assistance','제공한 도움'],['response','학생의 반응'],['strength','강점 · 변화'],['nextSupport','다음 지원'],['iepGoal','연결한 개별화교육 목표']];
function observationDetails(note){const entries=observationExtraFields.filter(([key])=>note[key]);return entries.length?`<dl class="observation-details">${entries.map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(note[key])}</dd></div>`).join('')}</dl>`:'';}
function recordFieldMarkup(field,item){const [key,label,kind,optional]=field,val=item[key]??'',required=optional?'':'required';const hints={activity:'예: 수학 시간, 물건값 계산하기',content:'학생이 실제로 한 행동이나 말을 적어 주세요.',assistance:'예: 계산 순서 그림을 책상 위에 제시함.',response:'예: 그림을 확인하며 다음 문제도 풀었음.',strength:'예: 안내 없이 준비물을 스스로 챙김.',nextSupport:'예: 같은 그림을 제공하고 혼자 시작할 시간을 기다리기.',iepGoal:'해당 활동과 연결되는 목표가 있을 때 적어 주세요.'};let input;if(Array.isArray(kind))input=`<select name="${key}" ${required}>${kind.map(v=>{const [k,l]=Array.isArray(v)?v:[v,v];return `<option value="${esc(k)}" ${String(val)===String(k)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;else if(kind==='textarea')input=`<textarea name="${key}" maxlength="6000" placeholder="${esc(hints[key]||'')}" ${required}>${esc(val)}</textarea>`;else input=`<input name="${key}" type="${kind}" value="${esc(val)}" placeholder="${esc(hints[key]||'')}" ${required} ${kind==='number'?'min="0" max="10000000000" step="1"':''} ${kind==='text'?'maxlength="200"':''}>`;return `<label class="field">${label}${optional?' (선택)':''}${input}</label>`;}
function recordFieldsMarkup(type,fields,item){if(type!=='notes')return fields.map(f=>recordFieldMarkup(f,item)).join('');const extra=new Set(observationExtraFields.map(([key])=>key));return `<p class="observation-help">활동과 학생이 실제로 한 행동을 짧고 구체적으로 남겨 주세요.</p>${fields.filter(f=>!extra.has(f[0])).map(f=>recordFieldMarkup(f,item)).join('')}<details class="observation-options" ${observationExtraFields.some(([key])=>item[key])?'open':''}><summary>도움 · 반응 · 다음 지원 기록하기 (선택)</summary><p class="small muted">필요한 항목만 작성해도 됩니다.</p>${fields.filter(f=>extra.has(f[0])).map(f=>recordFieldMarkup(f,item)).join('')}</details>`;}
function openForm(type,id='',student=''){if(['notes','contacts'].includes(type)&&!state.students.length){toast('학생을 먼저 등록해 주세요.');go('students');openForm('students');return;}const item=state[type].find(x=>x.id===id)||{date:page==='events'?selectedDate:today(),time:type==='notes'?'':'09:00',student:student||state.students[0]?.id,number:state.students.reduce((n,s)=>Math.max(n,Number(s.number)||0),0)+1,quantity:1};const fs=fields(type);$('#modal').innerHTML=`<form id="record-form"><div class="modal-head"><h2>${labels[type]} ${id?'수정':'추가'}</h2><button type="button" class="text-btn" data-action="close" aria-label="닫기">${icon('close')}</button></div>${recordFieldsMarkup(type,fs,item)}<div class="modal-foot"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary" type="submit">저장하기</button></div></form>`;modalSave=data=>{const current=state[type].find(x=>x.id===id);for(const [k,,kind]of fs){if(typeof data[k]==='string')data[k]=data[k].trim();if(kind==='number')data[k]=Number(data[k]);}if(type==='notes'&&(!data.content||!data.activity)){toast('활동 · 상황과 관찰 내용을 입력해 주세요.');return false;}if(type==='students'){if(!data.name){toast('학생 이름을 입력해 주세요.');return false;}if(!Number.isInteger(data.number)||data.number<1){toast('학생 번호는 1 이상의 정수로 입력해 주세요.');return false;}if(state.students.some(s=>s.id!==id&&Number(s.number)===data.number)){toast('이미 사용하는 번호입니다. 다른 번호를 입력해 주세요.');return false;}}if(type==='links'&&safeUrl(data.url)==='#'){toast('http 또는 https 주소를 입력해 주세요.');return false;}const previous=state[type].map(x=>({...x}));if(current)Object.assign(current,data);else state[type].push({id:uid(),...data,...(type==='tasks'?{done:false}:{}),...(type==='checks'?{checked:[]}:{} )});if(!persist()){state[type]=previous;return false;}renderContent();toast('저장했어요.');return true;};$('#modal').showModal();}
function confirmBox(title,message,action){$('#modal').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2></div><p class="sub">${esc(message)}</p><div class="modal-foot"><button class="btn" data-action="close">취소</button><button class="btn primary" id="confirm-ok">확인</button></div>`;$('#confirm-ok').onclick=()=>{$('#modal').close();action();};$('#modal').showModal();}
function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows,name){download('\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),name,'text/csv;charset=utf-8');}
function validateBackup(d){if(!d||d.version!==1||typeof d.className!=='string'||typeof d.teacher!=='string'||!Number.isFinite(d.budget)||d.budget<0)return false;if(['schoolName','grade','room'].some(k=>d[k]!==undefined&&typeof d[k]!=='string')||(d.schoolYear!==undefined&&(!Number.isInteger(d.schoolYear)||d.schoolYear<1900||d.schoolYear>2200)))return false;const required={students:['id','name','support'],tasks:['id','title','category','date'],events:['id','title','date','time'],notes:['id','student','date','content'],contacts:['id','student','date','content'],checks:['id','title','date'],expenses:['id','title','date'],items:['id','title'],links:['id','title','url']};for(const [key,props]of Object.entries(required)){if(!Array.isArray(d[key])||d[key].length>100000)return false;const ids=new Set();for(const r of d[key]){if(!r||props.some(p=>typeof r[p]!=='string')||ids.has(r.id))return false;ids.add(r.id);if(key==='notes'&&['time','domain','activity','assistance','response','strength','nextSupport','iepGoal'].some(k=>r[k]!==undefined&&typeof r[k]!=='string'))return false;if(key==='students'&&r.memo!==undefined&&typeof r.memo!=='string')return false;if(key==='checks'&&(!Array.isArray(r.checked)||r.checked.some(v=>typeof v!=='string')))return false;if(key==='links'&&safeUrl(r.url)==='#')return false;if(key==='expenses'&&(!Number.isFinite(r.amount)||r.amount<0))return false;}}return d.attendance&&typeof d.attendance==='object'&&!Array.isArray(d.attendance)&&d.daily&&typeof d.daily==='object'&&!Array.isArray(d.daily);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.page){go(d.page);return;}if(d.add){openForm(d.add,'',d.student);return;}if(d.edit){openForm(d.edit,d.id);return;}if(d.delete){const type=d.delete,id=d.id;confirmBox(`${labels[type]} 삭제`,'이 항목을 삭제할까요? 학생을 삭제하면 연결된 학생 기록과 연락 기록도 삭제됩니다.',()=>{state[type]=state[type].filter(x=>x.id!==id);if(type==='students'){state.notes=state.notes.filter(x=>x.student!==id);state.contacts=state.contacts.filter(x=>x.student!==id);state.checks.forEach(c=>c.checked=c.checked.filter(x=>x!==id));Object.values(state.attendance).forEach(a=>delete a[id]);}persist();renderContent();toast('삭제했어요.');});return;}if(d.checkTab){selectedCheck=d.checkTab;renderContent();return;}const action=d.action;if(action==='close')$('#modal').close();if(action==='edit-class')editClassInfo();if(action==='menu')document.body.classList.toggle('nav-open');if(action==='today'){selectedDate=today();renderContent();}if(action==='export'){download(JSON.stringify(state,null,2),`하루반-${activeYear}학년도-${today()}.json`,'application/json');toast('백업 파일을 내려받았어요.');}if(action==='import')$('#import-file').click();if(action==='fresh'||action==='sample')confirmBox(action==='fresh'?'새 학급으로 시작하기':'예시 자료 불러오기','현재 학년도의 기록이 교체됩니다. 필요한 기록은 먼저 백업해 주세요.',()=>{const previous=state;state={...(action==='fresh'?blank():sample()),schoolYear:activeYear};if(!persist()){state=previous;return;}go('home');toast('준비되었어요. 설정에서 학급 이름을 바꿀 수 있어요.');});if(action==='all-present')confirmBox('모두 출석으로 표시',`${selectedDate}의 모든 학생을 출석으로 표시할까요? 기존 출결 상태가 변경됩니다.`,()=>{state.attendance[selectedDate]??={};state.students.forEach(s=>{state.attendance[selectedDate][s.id]={...state.attendance[selectedDate][s.id],status:'출석'};});persist();renderContent();toast('모두 출석으로 표시했어요.');});if(action==='check-all'){const c=state.checks.find(x=>x.id===selectedCheck);if(c){c.checked=state.students.map(s=>s.id);persist();renderContent();toast('모두 확인했어요.');}}if(action==='attendance-xlsx'){try{download(AttendanceXlsx.build(state,selectedDate),`출결-${selectedDate}.xlsx`,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('출결 엑셀 파일을 내려받았어요.');}catch{toast('엑셀 파일을 만들지 못했어요. 날짜를 확인하고 다시 시도해 주세요.');}};if(action==='expenses-csv')csv([['날짜','사용 내역','분류','금액'],...state.expenses.map(e=>[e.date,e.title,e.category,e.amount])],`학급지출-${today()}.csv`);});
document.addEventListener('input',e=>{if(e.target.id==='search'&&!e.isComposing){filter=e.target.value;renderContent();}if(e.target.id==='daily-note'){state.daily[today()]=e.target.value;if(persist())$('#memo-status').textContent='저장됨';}});
document.addEventListener('change',e=>{const el=e.target,d=el.dataset;if(el.id==='date-select'){selectedDate=el.value||today();renderContent();}if(el.id==='student-filter'){studentFilter=el.value;renderContent();}if(d.task){state.tasks.find(x=>x.id===d.task).done=el.checked;persist();renderContent();}if(d.attendance||d.attendanceMemo){const id=d.attendance||d.attendanceMemo;state.attendance[selectedDate]??={};state.attendance[selectedDate][id]??={status:'미확인',memo:''};state.attendance[selectedDate][id][d.attendance?'status':'memo']=el.value;persist();toast('출결을 저장했어요.');}if(d.checkStudent){const c=state.checks.find(x=>x.id===selectedCheck);c.checked=c.checked.filter(x=>x!==d.checkStudent);if(el.checked)c.checked.push(d.checkStudent);persist();renderContent();}if(el.id==='import-file'&&el.files[0])importSchoolYears(el);});
document.addEventListener('submit',e=>{if(e.target.id==='record-form'){e.preventDefault();if(modalSave(Object.fromEntries(new FormData(e.target))))$('#modal').close();}if(e.target.id==='settings-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const next={schoolName:d.schoolName.trim(),schoolYear:activeYear,grade:d.grade.trim(),room:d.room.trim(),className:d.className.trim(),teacher:d.teacher.trim(),budget:Number(d.budget)};if(!next.className||!next.teacher){toast('학급 이름과 담임 이름을 입력해 주세요.');return;}if(!Number.isInteger(next.schoolYear)||next.schoolYear<1900||next.schoolYear>2200||!Number.isFinite(next.budget)||next.budget<0||next.budget>10000000000){toast('학년도와 예산을 확인해 주세요.');return;}const previous={...state};Object.assign(state,next);if(!persist()){state=previous;return;}if($('#modal').open)$('#modal').close();shell();toast('학급 정보를 저장했어요.');}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
persist();shell();
